<script setup lang="ts">
import {computed,onMounted,reactive,ref} from 'vue';
import NxAlert from '../../components/ui/NxAlert.vue';import NxBadge from '../../components/ui/NxBadge.vue';import NxButton from '../../components/ui/NxButton.vue';import NxCard from '../../components/ui/NxCard.vue';import NxConfirmDialog from '../../components/ui/NxConfirmDialog.vue';import NxModal from '../../components/ui/NxModal.vue';import NxPageHeader from '../../components/ui/NxPageHeader.vue';import NxTableShell from '../../components/ui/NxTableShell.vue';import NxToolbar from '../../components/ui/NxToolbar.vue';
import{createVlan,deleteMgmtVlan,deleteVlan,getVlanSummary,listMgmtVlans,listOltOptions,listOltPorts,listVlans,retryVlan,saveMgmtVlan,updateVlan}from'./api';import type{MgmtVlanRow,OltOption,OltPortOption,VlanPayload,VlanRow,VlanSummary,VlanType}from'./contracts';
type Tab='cvlan'|'svlan'|'mgmt';type Pending={kind:'vlan'|'mgmt';row:VlanRow|MgmtVlanRow};
const tab=ref<Tab>('cvlan'),search=ref(''),loading=ref(false),saving=ref(false),error=ref(''),notice=ref(''),modalError=ref('');const vlanOpen=ref(false),mgmtOpen=ref(false),outputOpen=ref(false);const editing=ref<VlanRow|null>(null),editingMgmt=ref<MgmtVlanRow|null>(null),pendingDelete=ref<Pending|null>(null),pendingRetry=ref<VlanRow|null>(null),output=ref('');
const summary=ref<VlanSummary>({total_vlans:0,total_c_vlans:0,total_s_vlans:0,deployed_count:0}),vlans=ref<VlanRow[]>([]),mgmtVlans=ref<MgmtVlanRow[]>([]),olts=ref<OltOption[]>([]),ports=ref<OltPortOption[]>([]);
const vlanForm=reactive<VlanPayload>({olt_id:0,olt_port_id:null,parent_svlan_id:null,vlan_id:0,vlan_type:'C_VLAN',name:'',description:''});const mgmtForm=reactive({olt_id:0,olt_port_id:0,mgmt_vlan:0,description:''});
const activeType=computed<VlanType>(()=>tab.value==='svlan'?'S_VLAN':'C_VLAN');const normalized=computed(()=>search.value.trim().toLowerCase());const rows=computed(()=>vlans.value.filter(r=>r.vlan_type===activeType.value&&(!normalized.value||JSON.stringify(r).toLowerCase().includes(normalized.value))));const mgmtRows=computed(()=>mgmtVlans.value.filter(r=>!normalized.value||JSON.stringify(r).toLowerCase().includes(normalized.value)));const parentOptions=computed(()=>vlans.value.filter(r=>r.vlan_type==='S_VLAN'&&r.deployment_status==='DEPLOYED'&&Number(r.olt_id)===Number(vlanForm.olt_id)));const assignedSvlanPortIds=computed(()=>new Set(vlans.value.filter(r=>r.vlan_type==='S_VLAN'&&Number(r.olt_id)===Number(vlanForm.olt_id)&&r.olt_port_id&&(!editing.value||Number(r.id)!==Number(editing.value.id))).map(r=>Number(r.olt_port_id))));const allowedPorts=computed(()=>ports.value.filter(p=>{const values=[p.port_type,p.board_type,p.board_name,p.board].map(v=>String(v||'').toUpperCase());const isGpon=values.some(v=>v==='GPON'||v.includes('CGHF')||v.includes('CSHF'));return isGpon&&!assignedSvlanPortIds.value.has(Number(p.id));}));
const mgmtPorts=computed(()=>ports.value.filter(p=>[p.board_type,p.board_name,p.board].some(v=>String(v||'').toUpperCase().includes('H901MPSA'))));
const deleteCopy=computed(()=>{const row=pendingDelete.value?.row;if(!row)return{title:'Delete record?',description:'',label:'Delete'};if(pendingDelete.value?.kind==='mgmt')return{title:'Delete MGMT-VLAN?',description:`MGMT-VLAN ${(row as MgmtVlanRow).mgmt_vlan} will be removed from the OLT and its saved configuration.`,label:'Delete MGMT-VLAN'};const vlan=row as VlanRow;return{title:`Delete ${vlan.vlan_type==='S_VLAN'?'S-VLAN':'C-VLAN'} ${vlan.vlan_id}?`,description:'This removes the VLAN from the OLT, deletes its database record, and forgets its managed BNG interface.',label:'Delete VLAN'};});
function clear(){error.value='';notice.value='';modalError.value='';}function oltLabel(id:number){const o=olts.value.find(x=>Number(x.id)===Number(id));return o?.name?`${o.name} (${o.ip_address||'No IP'})`:o?.ip_address||`OLT #${id}`;}function statusTone(s?:string):'success'|'danger'|'warning'|'neutral'{const v=String(s||'').toUpperCase();return v==='DEPLOYED'?'success':v==='FAILED'?'danger':v==='PENDING'?'warning':'neutral';}function formatDate(value?:string|null){return value?new Date(value.replace(' ','T')).toLocaleString():'Not deployed';}
async function load(showNotice=false){loading.value=true;clear();try{const[s,v,m,o]=await Promise.all([getVlanSummary(),listVlans(),listMgmtVlans(),listOltOptions()]);summary.value=s;vlans.value=v||[];mgmtVlans.value=m||[];olts.value=o||[];if(showNotice)notice.value='VLAN data refreshed.';}catch(reason){error.value=reason instanceof Error?reason.message:'Failed to load VLAN Management.';}finally{loading.value=false;}}
async function changeOlt(){vlanForm.parent_svlan_id=null;vlanForm.olt_port_id=null;ports.value=vlanForm.vlan_type==='S_VLAN'&&vlanForm.olt_id?await listOltPorts(vlanForm.olt_id):[];}
async function openNew(){clear();editing.value=null;Object.assign(vlanForm,{olt_id:Number(olts.value[0]?.id||0),olt_port_id:null,parent_svlan_id:null,vlan_id:0,vlan_type:activeType.value,name:'',description:''});ports.value=vlanForm.vlan_type==='S_VLAN'&&vlanForm.olt_id?await listOltPorts(vlanForm.olt_id):[];vlanOpen.value=true;}
function openEdit(row:VlanRow){clear();editing.value=row;Object.assign(vlanForm,{olt_id:Number(row.olt_id),olt_port_id:row.olt_port_id||null,parent_svlan_id:row.parent_svlan_id||null,vlan_id:Number(row.vlan_id),vlan_type:row.vlan_type,name:row.name||'',description:row.description||''});vlanOpen.value=true;}
async function submitVlan(){modalError.value='';if(!vlanForm.name.trim()){modalError.value='Name is required.';return;}if(!vlanForm.olt_id||vlanForm.vlan_id<1||vlanForm.vlan_id>4094){modalError.value='Select an OLT and enter a VLAN ID from 1 to 4094.';return;}if(vlanForm.vlan_type==='S_VLAN'&&!vlanForm.olt_port_id){modalError.value='OLT Port is required for S-VLAN.';return;}if(vlanForm.vlan_type==='C_VLAN'&&!vlanForm.parent_svlan_id){modalError.value='A deployed parent S-VLAN is required for C-VLAN.';return;}saving.value=true;try{const result=editing.value?await updateVlan(editing.value.id,{...vlanForm}):await createVlan({...vlanForm});vlanOpen.value=false;await load(false);notice.value=result.message||(editing.value?'VLAN updated.':'VLAN created and deployment completed.');}catch(reason){modalError.value=reason instanceof Error?reason.message:'VLAN operation failed.';}finally{saving.value=false;}}
async function changeMgmtOlt(){mgmtForm.olt_port_id=0;ports.value=mgmtForm.olt_id?await listOltPorts(mgmtForm.olt_id):[];}async function openMgmt(row?:MgmtVlanRow){clear();editingMgmt.value=row||null;Object.assign(mgmtForm,{olt_id:Number(row?.olt_id||olts.value[0]?.id||0),olt_port_id:Number(row?.olt_port_id||0),mgmt_vlan:Number(row?.mgmt_vlan||0),description:row?.description||''});ports.value=mgmtForm.olt_id?await listOltPorts(mgmtForm.olt_id):[];mgmtOpen.value=true;}async function submitMgmt(){modalError.value='';if(!mgmtForm.olt_id||!mgmtForm.olt_port_id||mgmtForm.mgmt_vlan<1||mgmtForm.mgmt_vlan>4094){modalError.value='Select an OLT, an H901MPSA port, and enter a MGMT-VLAN from 1 to 4094.';return;}saving.value=true;try{const result=await saveMgmtVlan({id:editingMgmt.value?.id||null,...mgmtForm});mgmtOpen.value=false;await load(false);notice.value=result.message||'MGMT-VLAN saved and deployment completed.';}catch(reason){modalError.value=reason instanceof Error?reason.message:'MGMT-VLAN operation failed.';}finally{saving.value=false;}}
async function executeDelete(){if(!pendingDelete.value)return;saving.value=true;modalError.value='';try{const result=pendingDelete.value.kind==='vlan'?await deleteVlan((pendingDelete.value.row as VlanRow).id):await deleteMgmtVlan((pendingDelete.value.row as MgmtVlanRow).id);pendingDelete.value=null;await load(false);notice.value=result.message||'VLAN removed successfully.';}catch(reason){modalError.value=reason instanceof Error?reason.message:'Delete failed.';}finally{saving.value=false;}}function showOutput(row:VlanRow){let value=row.deployment_output||'No deployment output stored.';try{value=JSON.stringify(JSON.parse(value),null,2);}catch{}output.value=value;outputOpen.value=true;}
async function executeRetry(){if(!pendingRetry.value)return;const vlan=pendingRetry.value;saving.value=true;modalError.value='';try{const result=await retryVlan(vlan.id);pendingRetry.value=null;await load(false);notice.value=result.message||`VLAN ${vlan.vlan_id} deployed successfully.`;}catch(reason){modalError.value=reason instanceof Error?reason.message:'Retry failed.';}finally{saving.value=false;}}
onMounted(()=>void load());
</script>
<template><div class="space-y-4 pb-8 text-[var(--nx-text)]"><NxPageHeader eyebrow="OLT VLAN deployment" title="VLAN Management" description="Manage C-VLAN, S-VLAN, and TR069 management VLAN definitions across the OLT and BNG."><template #actions><NxButton variant="secondary" :disabled="loading" @click="load(true)">{{loading?'Refreshing…':'Refresh'}}</NxButton><NxButton v-if="tab!=='mgmt'" :disabled="!olts.length" @click="openNew">New {{tab==='svlan'?'S-VLAN':'C-VLAN'}}</NxButton><NxButton v-else :disabled="!olts.length" @click="openMgmt()">Set MGMT-VLAN</NxButton></template></NxPageHeader><NxAlert v-if="error||notice" :tone="error?'danger':'success'">{{error||notice}}</NxAlert><NxAlert v-if="!loading&&!olts.length" tone="warning">No OLT is available. Add an OLT before creating VLANs.</NxAlert>
<section class="grid gap-3 sm:grid-cols-2 xl:grid-cols-4"><NxCard v-for="item in [['Total VLANs',summary.total_vlans,'All deployable definitions'],['C-VLAN',summary.total_c_vlans,'Customer-side VLANs'],['S-VLAN',summary.total_s_vlans,'Service-side QinQ VLANs'],['Deployed',summary.deployed_count,'Successfully pushed to OLT']]" :key="String(item[0])"><p class="text-xs font-semibold uppercase text-[var(--nx-text-muted)]">{{item[0]}}</p><p class="mt-2 text-2xl font-bold">{{item[1]}}</p><p class="mt-1 text-xs text-[var(--nx-text-muted)]">{{item[2]}}</p></NxCard></section>
<NxToolbar><div class="flex flex-col gap-3 lg:flex-row lg:items-center lg:justify-between"><div role="tablist" aria-label="VLAN views" class="flex flex-wrap gap-2"><button v-for="item in [['cvlan','C-VLAN'],['svlan','S-VLAN'],['mgmt','MGMT-VLAN']]" :key="item[0]" class="min-h-10 rounded-md px-3 text-sm font-semibold" :class="tab===item[0]?'bg-brand-600 text-white':'bg-[var(--nx-surface-muted)]'" @click="tab=item[0] as Tab">{{item[1]}}</button></div><input v-model="search" type="search" placeholder="Search VLAN, OLT, status…" class="min-h-11 w-full rounded-md bg-[var(--nx-surface-muted)] px-4 text-sm lg:max-w-sm"></div></NxToolbar>
<section v-if="tab!=='mgmt'"><NxTableShell min-width="980px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase text-[var(--nx-text-muted)]"><tr><th class="px-4 py-3">VLAN</th><th class="px-4 py-3">OLT / Port</th><th class="px-4 py-3">Status</th><th class="px-4 py-3">Name</th><th class="px-4 py-3">Description</th><th class="px-4 py-3">Deployed</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!rows.length"><td colspan="7" class="px-4 py-12 text-center">No {{tab==='svlan'?'S-VLAN':'C-VLAN'}} records found.</td></tr><tr v-for="row in rows" :key="row.id"><td class="px-4 py-3"><p class="font-mono font-bold">VLAN {{row.vlan_id}}</p><p class="text-xs text-[var(--nx-text-muted)]">Record #{{row.id}}</p></td><td class="px-4 py-3"><p>{{row.olt_ip_address||oltLabel(row.olt_id)}}</p><p class="text-xs text-[var(--nx-text-muted)]">{{row.olt_port_path?`Port ${row.olt_port_path}`:`OLT ID ${row.olt_id}`}}</p></td><td class="px-4 py-3"><NxBadge :tone="statusTone(row.deployment_status)">{{row.deployment_status||'UNKNOWN'}}</NxBadge></td><td class="px-4 py-3 font-semibold">{{row.name}}</td><td class="max-w-xs px-4 py-3 text-sm">{{row.description||'—'}}</td><td class="px-4 py-3 text-sm">{{formatDate(row.deployed_at)}}</td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" @click="showOutput(row)">Output</NxButton><NxButton v-if="String(row.deployment_status).toUpperCase()==='FAILED'" variant="secondary" @click="pendingRetry=row">Retry</NxButton><NxButton variant="secondary" @click="openEdit(row)">Edit</NxButton><NxButton variant="danger" @click="pendingDelete={kind:'vlan',row}">Delete</NxButton></div></td></tr></tbody></NxTableShell></section>
<section v-else><NxTableShell min-width="900px"><thead class="bg-[var(--nx-surface-muted)] text-xs uppercase text-[var(--nx-text-muted)]"><tr><th class="px-4 py-3">OLT</th><th class="px-4 py-3">H901MPSA Port</th><th class="px-4 py-3">MGMT-VLAN</th><th class="px-4 py-3">Description</th><th class="px-4 py-3">Created</th><th class="px-4 py-3 text-right">Actions</th></tr></thead><tbody><tr v-if="!mgmtRows.length"><td colspan="6" class="px-4 py-12 text-center">No MGMT-VLAN records found.</td></tr><tr v-for="row in mgmtRows" :key="row.id"><td class="px-4 py-3"><p class="font-semibold">{{row.olt_ip_address||oltLabel(row.olt_id)}}</p><p class="text-xs text-[var(--nx-text-muted)]">OLT ID {{row.olt_id}}</p></td><td class="px-4 py-3 font-mono">{{row.olt_port_path||'Not assigned'}}</td><td class="px-4 py-3 font-mono font-bold">VLAN {{row.mgmt_vlan}}</td><td class="px-4 py-3">{{row.description||'—'}}</td><td class="px-4 py-3">{{formatDate(row.created_at)}}</td><td class="px-4 py-3"><div class="flex justify-end gap-2"><NxButton variant="secondary" @click="openMgmt(row)">Edit</NxButton><NxButton variant="danger" @click="pendingDelete={kind:'mgmt',row}">Delete</NxButton></div></td></tr></tbody></NxTableShell></section>
<NxModal :open="vlanOpen" :title="editing?`Edit ${vlanForm.vlan_type==='S_VLAN'?'S-VLAN':'C-VLAN'} ${vlanForm.vlan_id}`:`New ${vlanForm.vlan_type==='S_VLAN'?'S-VLAN':'C-VLAN'}`" description="New VLANs are immediately deployed to the OLT and their managed BNG interface is created." @close="vlanOpen=false"><form @submit.prevent="submitVlan"><NxAlert v-if="modalError" tone="danger" class="mx-6 mt-5">{{modalError}}</NxAlert><NxAlert v-if="!editing" tone="warning" class="mx-6 mt-5">Save & Deploy changes live OLT and BNG interface state.</NxAlert><div class="grid gap-4 bg-[var(--nx-canvas)] p-6 md:grid-cols-2"><label class="grid gap-1.5 text-sm font-semibold">OLT<select v-model.number="vlanForm.olt_id" required :disabled="Boolean(editing)" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3" @change="changeOlt"><option :value="0">Select OLT</option><option v-for="olt in olts" :key="olt.id" :value="Number(olt.id)">{{oltLabel(olt.id)}}</option></select></label><label v-if="vlanForm.vlan_type==='S_VLAN'" class="grid gap-1.5 text-sm font-semibold">GPON OLT Port<select v-model.number="vlanForm.olt_port_id" required :disabled="Boolean(editing)" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"><option :value="null">Select port</option><option v-for="port in allowedPorts" :key="port.id" :value="Number(port.id)">{{port.frame??0}}/{{port.slot??0}}/{{port.port??0}}</option></select></label><label v-else class="grid gap-1.5 text-sm font-semibold">Parent deployed S-VLAN<select v-model.number="vlanForm.parent_svlan_id" required :disabled="Boolean(editing)" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"><option :value="null">Select S-VLAN</option><option v-for="parent in parentOptions" :key="parent.id" :value="parent.id">S-VLAN {{parent.vlan_id}} · {{parent.name}}</option></select></label><label class="grid gap-1.5 text-sm font-semibold">VLAN ID<input v-model.number="vlanForm.vlan_id" type="number" min="1" max="4094" required :readonly="Boolean(editing)" class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label><label class="grid gap-1.5 text-sm font-semibold">Name<input v-model="vlanForm.name" maxlength="64" required class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label><label class="grid gap-1.5 text-sm font-semibold md:col-span-2">Description<textarea v-model="vlanForm.description" rows="3" class="rounded-md bg-[var(--nx-surface)] p-3"></textarea></label></div><div class="flex justify-end gap-2 border-t border-[var(--nx-border)] p-5"><NxButton type="button" variant="secondary" @click="vlanOpen=false">Cancel</NxButton><NxButton type="submit" :disabled="saving">{{saving?'Working…':editing?'Update Details':'Save & Deploy'}}</NxButton></div></form></NxModal>
<NxModal :open="mgmtOpen" :title="editingMgmt?'Edit MGMT-VLAN':'Set MGMT-VLAN'" description="Saving creates the TR069 management VLAN and applies it to the selected H901MPSA port." @close="mgmtOpen=false"><form @submit.prevent="submitMgmt"><NxAlert v-if="modalError" tone="danger" class="mx-6 mt-5">{{modalError}}</NxAlert><NxAlert tone="warning" class="mx-6 mt-5">This operation changes live OLT configuration.</NxAlert><div class="grid gap-4 bg-[var(--nx-canvas)] p-6"><label class="grid gap-1.5 text-sm font-semibold">OLT<select v-model.number="mgmtForm.olt_id" required class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3" @change="changeMgmtOlt"><option :value="0">Select OLT</option><option v-for="olt in olts" :key="olt.id" :value="Number(olt.id)">{{oltLabel(olt.id)}}</option></select></label><label class="grid gap-1.5 text-sm font-semibold">H901MPSA Port<select v-model.number="mgmtForm.olt_port_id" required class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"><option :value="0">Select H901MPSA port</option><option v-for="port in mgmtPorts" :key="port.id" :value="Number(port.id)">{{port.frame??0}}/{{port.slot??0}}/{{port.port??0}}</option></select></label><NxAlert v-if="mgmtForm.olt_id&&!mgmtPorts.length" tone="warning">No H901MPSA ports were discovered for this OLT.</NxAlert><label class="grid gap-1.5 text-sm font-semibold">MGMT-VLAN<input v-model.number="mgmtForm.mgmt_vlan" type="number" min="1" max="4094" required class="min-h-11 rounded-md bg-[var(--nx-surface)] px-3"></label><label class="grid gap-1.5 text-sm font-semibold">Description<textarea v-model="mgmtForm.description" rows="3" class="rounded-md bg-[var(--nx-surface)] p-3"></textarea></label></div><div class="flex justify-end gap-2 border-t border-[var(--nx-border)] p-5"><NxButton type="button" variant="secondary" @click="mgmtOpen=false">Cancel</NxButton><NxButton type="submit" :disabled="saving">{{saving?'Deploying…':editingMgmt?'Update & Deploy':'Save & Deploy'}}</NxButton></div></form></NxModal>
<NxModal :open="outputOpen" title="Deployment output" description="Stored OLT and BNG automation result." max-width="56rem" @close="outputOpen=false"><pre class="m-6 max-h-[65vh] overflow-auto rounded-md bg-slate-950 p-4 text-xs text-slate-100">{{output}}</pre><template #footer><NxButton @click="outputOpen=false">Close</NxButton></template></NxModal><NxConfirmDialog :open="Boolean(pendingRetry)" title="Retry VLAN deployment?" :description="pendingRetry?`Retry ${pendingRetry.vlan_type==='S_VLAN'?'S-VLAN':'C-VLAN'} ${pendingRetry.vlan_id} on its configured OLT and BNG. Existing commands are idempotent.`:''" confirm-label="Retry Deployment" :busy="saving" :error="modalError" @close="pendingRetry=null" @confirm="executeRetry" /><NxConfirmDialog :open="Boolean(pendingDelete)" :title="deleteCopy.title" :description="deleteCopy.description" :confirm-label="deleteCopy.label" danger :busy="saving" :error="modalError" @close="pendingDelete=null" @confirm="executeDelete" /></div></template>
